BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('gcp-pca-g-q51', '設計・計画',
   '世界中の美術館と連携するアーカイブ管理クラウドへの移行プロジェクトでは、既存のオンプレミスデータセンターと Google Cloud 間で Cloud VPN を使用して安全な通信を確保しつつ、段階的にシステムを移行していく必要がある。オンプレ資産へのアクセスを常時維持しながら GCP 環境を設計する場合、ネットワーク構成として最も適切なのはどれか。',
   NULL,
   '["オンプレと重複しない CIDR を GCP 側の VPC に割り当てる","プライマリとセカンダリ両方のサブネットにオンプレと同一のアドレス空間を設定する","セカンダリ IP 範囲でオンプレと同じ CIDR を定義し、DNS で名前解決を優先させる","GCP 側にオンプレと同一の CIDR 範囲を割り当て、ルートの優先度で制御する"]',
   0, NULL, 'single',
   '{"asked":"Cloud VPN でオンプレと GCP を繋ぐとき、IP アドレス設計として何を守ればハイブリッド接続が安定するか。",
     "think":"Cloud VPN は既存のオンプレ CIDR とは別のトンネルを張るだけで、双方の IP 空間が重複していても止めてはくれない。重複した CIDR が両側に存在すると、パケットがどちらのネットワーク宛かをルーターが判断できず、経路の競合や到達不能が起こる。だから設計の出発点は「GCP 側の VPC にオンプレと重ならない CIDR を割り当てる」ことになる。これさえ守れば、あとは通常の VPN ルーティングで双方向の到達性が保てる。",
     "vs":"セカンダリ IP 範囲や DNS の名前解決順序、ルートの優先度は、いずれも IP レベルで重複が起きたあとの症状を緩和しようとする対症療法。重複そのものをなくす一意な CIDR 設計に代わるものではない。",
     "opt":["正解。オンプレと重ならない一意な CIDR を GCP 側に割り当てることで、ルーティングの競合を根本から防げる。","プライマリ／セカンダリの両方でオンプレと同じアドレス空間を使うと、重複 CIDR がむしろ増え、VPN 経路はほぼ確実に破綻する。","セカンダリ IP 範囲や DNS の解決順序を変えても、IP レベルの経路競合という根本原因は解消されない。","同一 CIDR を複数経路に持たせたままルート優先度を調整しても、ルーティングの混乱や到達不能を完全には防げない。"]}'),

  ('gcp-pca-g-q52', 'インフラのプロビジョニングと管理',
   'スタジアム内の IoT 管理システムのプロトタイプを Google Cloud 上に構築することになり、開発チームからは Kubernetes の Deployment マニフェストのみが提供された。現在はまだクラスタやその他のインフラは一切存在していない。最短でこのマニフェストを本番動作させるために最も適切な手順はどれか。',
   NULL,
   '["gcloud で GKE クラスタを作成し、kubectl apply -f でデプロイする","Cloud Shell から Cloud Run にクラスタを自動生成させ、マニフェストを直接投入する","Terraform で GKE クラスタを構築し、gcloud を用いてマニフェストをアップロードする","Cloud Build を使ってクラスタとマニフェストをパイプライン展開する"]',
   0, NULL, 'single',
   '{"asked":"Kubernetes マニフェストが手元にあり、クラスタもまだ無い状態から、最短で本番稼働させるにはどの手順が適切か。",
     "think":"すでに動作確認済みのマニフェストがあるなら、あとはそれを実行できる GKE クラスタを立てて流し込むだけでよい。gcloud container clusters create でクラスタを作成し、get-credentials で kubectl の認証情報を取得すれば、そのまま kubectl apply -f でマニフェストを適用できる。追加の変換や構成管理レイヤーを挟む理由がない。",
     "vs":"Terraform や Cloud Build を使う案は、継続的な IaC 運用や CI/CD パイプラインとしては妥当でも、今回の「最短でこのマニフェストを動かす」という即時性の要件には工程が多すぎる。Cloud Run はそもそも Kubernetes クラスタを構築する手段ではない。",
     "opt":["正解。gcloud でクラスタを作成し get-credentials で認証を取得すれば、kubectl apply -f で既存マニフェストをそのまま最短適用できる。","Cloud Run はコンテナの実行基盤であり、Kubernetes クラスタを構築する手段ではない。","Terraform は構成管理として有効だが、最短展開という観点では定義作成にステップが増え時間を要する。","Cloud Build のパイプライン構築には追加の定義やリソース準備が必要で、即時性に欠ける。"]}'),

  ('gcp-pca-g-q53', 'インフラのプロビジョニングと管理',
   '気象衛星のデータを処理する高性能画像解析アプリケーションは、多数の専用ライブラリと OS パッケージに依存している。このアプリを Compute Engine のマネージドインスタンスグループ（MIG）として運用し、観測状況に応じて自動スケーリングさせたい。新規インスタンス起動時の待機時間を極力短縮したい。最も適切な構成はどれか。',
   NULL,
   '["依存パッケージをすべて入れたカスタムイメージを作成し、そのイメージで MIG を構成する","インスタンス作成後に Cloud Build を用いてパッケージをデプロイする構成をテンプレート化する","Cloud Init を使ってインスタンス起動時に各種依存パッケージを取得・インストールする","MIG 作成後に Chef で構成管理を行い、パッケージを逐次反映する"]',
   0, NULL, 'single',
   '{"asked":"MIG のオートスケーリングで新規インスタンスが増えるたびに、依存ライブラリの準備を待たずに即戦力にするにはどうするか。",
     "think":"起動時にパッケージを取得・インストールする方式（Cloud Init、Chef、Cloud Build 経由のデプロイ）は、どれも「起動してから準備する」構造そのものは同じで、ネットワークやパッケージ取得の時間がそのまま起動待機時間に乗る。待機時間を削るには、準備の完了した状態をイメージとして固めておき、起動＝即実行可能にするしかない。すべての依存パッケージを事前に含んだカスタムイメージを作り、それを MIG のテンプレートに使うのが最短経路になる。",
     "vs":"Cloud Init やスタートアップスクリプトは「起動のたびにインストールをやり直す」方式なので、依存が重いアプリほど遅くなる。カスタムイメージは「インストール済みの状態を配る」方式なので、起動直後から処理を開始できる。",
     "opt":["正解。依存パッケージを事前に焼き込んだカスタムイメージを MIG のテンプレートに使えば、起動直後から処理を開始でき、スケーリングにも即応できる。","Cloud Build は CI/CD 向けのサービスであり、インスタンスごとのランタイム環境を即時に用意する用途には向かない。","起動スクリプトでの都度インストールはネットワーク状況に左右され、依存が多いほどブート時間が延びる。","Chef による構成適用も新規インスタンス起動のたびに時間がかかり、待機時間短縮という要件を満たさない。"]}'),

  ('gcp-pca-g-q54', 'セキュリティとコンプライアンス',
   '国際的な旅行予約プラットフォームでは、同一 VPC 内に Web／API／DB の三階層構成を採用している。要件として、通信経路を「Web → API → DB」に限定し、Web 層から DB 層への直接アクセスを禁止したい。また、将来的に VM が増えても運用負荷を最小限に抑えたい場合、最も適切な構成はどれか。',
   NULL,
   '["各階層にネットワークタグを付与し、VPC ファイアウォールで通信許可／拒否を制御する","カスタムルートで Web→API→DB の経路を明示的に指定する","各階層を異なるリージョンに配置し、地理的に分離する","各 VM に個別の iptables ルールを設定して通信制御する"]',
   0, NULL, 'single',
   '{"asked":"同一 VPC 内の三階層で、Web から DB への直接アクセスだけを禁止しつつ、VM が増えても運用負荷を増やさない通信制御はどう実現するか。",
     "think":"「Web→DB だけ禁止し、Web→API・API→DB は許可する」という要件は、経路（ルーティング）の問題ではなくアクセス許可の問題。VPC ファイアウォールルールに各階層のネットワークタグを条件として設定すれば、送信元タグと宛先タグの組み合わせで通信の可否を一元的に定義できる。新しい VM が増えても同じタグを付けるだけでルールが自動的に適用されるため、運用負荷も増えない。",
     "vs":"カスタムルートはパケットの経路選択を決める機能であり、アクセスの許可・拒否そのものは制御できない。リージョン分離や VM ごとの iptables 設定は、通信制御の目的には遠回りか、台数が増えるほど管理コストが膨らむ。",
     "opt":["正解。ネットワークタグを条件にした VPC ファイアウォールルールなら、送信元→宛先の組み合わせで通信を一元制御でき、VM が増えてもタグを付けるだけで済む。","カスタムルートは経路選択のための機能であり、アクセス許可・拒否の制御はできない。","リージョン分離は冗長構成向けの手段であり、同一 VPC 内の通信制御という要件には合わない。","VM ごとの iptables 設定は管理負荷が高く、台数が増えるほど変更への追従が難しくなる。"]}'),

  ('gcp-pca-g-q55', 'インフラのプロビジョニングと管理',
   'スマート工場の IoT 制御システムでは、各製造ラインごとに独立した処理ノードを GKE 上で運用している。これらのノードは、再起動やスケーリングのたびに自動で再作成されるが、外部システムとの通信では常に安定したホスト名が必要である。この要件を満たす Kubernetes の機能はどれか。',
   NULL,
   '["StatefulSet","HorizontalPodAutoscaler","ConfigMap","NetworkPolicy"]',
   0, NULL, 'single',
   '{"asked":"Pod が再作成されても外部から同じホスト名で参照し続けたいとき、どの Kubernetes リソースを使うか。",
     "think":"要件は「再作成されても名前が変わらないこと」。HorizontalPodAutoscaler は Pod 数の増減だけを担当し名前とは無関係、ConfigMap は設定値を配るだけ、NetworkPolicy は通信の許可・拒否を決めるだけで、いずれもホスト名の安定化には関与しない。Pod に順序付きの安定した名前（app-0, app-1 …）を割り当て、再起動後も同じ DNS 名で解決できるようにする機能は StatefulSet が持つ性質そのものであり、これが唯一この要件を満たす。",
     "vs":"Deployment 配下の Pod は再作成のたびに名前がランダムに変わるが、StatefulSet 配下の Pod は再作成後も同じ名前・同じ DNS エントリを保持する。この差が「安定したホスト名が必要」という要件の決め手になる。",
     "opt":["正解。StatefulSet は Pod に一貫性のあるホスト名と順序付きの名前を割り当て、再作成後も同じ DNS 名で解決できる。","HorizontalPodAutoscaler は Pod 数の自動調整を行うが、ホスト名の固定には関与しない。","ConfigMap は設定情報を管理する機能であり、Pod のホスト名制御は行わない。","NetworkPolicy は通信の許可・拒否ルールを制御するもので、DNS 名やホスト名の安定性には影響しない。"]}'),

  ('gcp-pca-g-q56', 'プロセスの分析と最適化',
   '火星の地表観測プロジェクトにおいて、探査車が収集した鉱物データを一時的にデータストアに保存している。研究チームは、複数の特定鉱物サンプルの識別子をもとに、それらの詳細データを素早くかつ効率的に取得したい。通信帯域と処理遅延を最小限に抑えるためには、どの方法が最適か。',
   NULL,
   '["取得対象の Key をすべて生成し、一括取得 API でまとめて読み出す","複数識別子を対象にしたフィルタクエリで一括検索を行う","各識別子に対応する参照キーを個別に生成し、順に読み出す","サンプル識別子ごとに別々の問い合わせを並列に実行する"]',
   0, NULL, 'single',
   '{"asked":"Key（識別子）が既にわかっているエンティティを複数まとめて取得するとき、最も帯域と遅延を抑えられる方法はどれか。",
     "think":"識別子が既知なら、クエリでインデックスを走査させる必要はない。Key を直接指定してバッチ get（一括取得 API）を呼べば、1 回のラウンドトリップで複数エンティティをまとめて取得でき、インデックス走査のコストも発生しない。フィルタクエリはインデックス走査を伴い、個別読み出しや並列実行はリクエスト数そのものが増えるため、どちらも一括 Key 取得より非効率になる。",
     "vs":"「クエリで探す」と「Key で直接引く」は別物。Key が既にわかっているなら探す必要はなく、直接引くバッチ get の方が常に速い。並列化はリクエスト数を減らす手段にはならない点にも注意。",
     "opt":["正解。既知の Key をまとめて渡す一括取得 API なら、インデックス走査なしで 1 回のラウンドトリップで複数エンティティを取得でき、帯域と遅延の両方を最小化できる。","複数識別子のフィルタクエリはインデックス走査が必要になり、Key 指定の一括取得に比べ遅延が大きくなる。","個別の Key で順に読み出す方式はリクエストが分割されるため、待機時間とリソース消費が増加する。","並列実行してもクエリ 1 件あたりの非効率さは変わらず、全体としては無駄が多くなる。"]}'),

  ('gcp-pca-g-q57', 'セキュリティとコンプライアンス',
   '大手製薬企業は、研究機関から得られた高機密性のゲノム解析データを Google Cloud Storage に移送する計画を立てている。顧客自身が管理する暗号鍵（CSEK）を用いて保存時の暗号化を義務づけており、オンプレミスからのデータアップロードにおいてこの要件を満たす必要がある。適切な構成方法として正しいものはどれか。',
   NULL,
   '["boto 設定ファイルに暗号鍵を指定し、gsutil でアップロードする","Cloud Console で鍵を設定後、Drag & Drop でファイルをアップロードする","gsutil の設定ファイルに IAM ロールのみ指定してアップロードを行う","Cloud Key Management Service (KMS) の鍵を指定して、gcloud cp で転送する"]',
   0, NULL, 'single',
   '{"asked":"顧客が自分で管理する暗号鍵（CSEK）で Cloud Storage への保存時暗号化を行うには、どの手段でアップロードすればよいか。",
     "think":"CSEK（顧客管理の暗号鍵）は、アップロードする側が鍵そのものをリクエストに渡す方式。gsutil はこの用途に対応しており、.boto 設定ファイルに暗号鍵を記述しておけば、以降の転送すべてに自動的にその鍵での暗号化が適用される。Cloud Console の Drag & Drop や IAM ロールの指定では鍵情報そのものを渡す手段がなく、CSEK の要件を満たせない。",
     "vs":"CSEK（顧客が鍵そのものを管理）と CMEK（Cloud KMS が鍵を管理）は似て非なるもの。Cloud KMS の鍵を指定する方法は CMEK であり、CSEK の要件とは別物になる。",
     "opt":["正解。.boto 設定ファイルに CSEK を記述して gsutil でアップロードすれば、一度の設定ですべての転送に暗号化が自動適用される。","コンソール操作や Drag & Drop では CSEK の鍵情報を指定する手段がなく、要件を満たせない。","IAM ロールの指定は暗号鍵そのものの指定にはならず、CSEK の暗号化ポリシーを満たさない。","Cloud KMS の鍵を指定する方法は CSEK ではなく CMEK（Cloud 管理鍵）であり、本件の要件とは異なる。"]}'),

  ('gcp-pca-g-q58', 'セキュリティとコンプライアンス',
   'スマート農業用の制御システムでは、各作物区画に設置されたセンサー収集アプリケーションが Compute Engine のオートスケーリング VM 上で稼働している。センサーと集計アプリ間の通信は、セキュリティ上、特定ポートと通信方向に限定する必要がある。IP アドレスやゾーンに依存せず、動的に増減するインスタンス間で安全な通信制御を行うには、どの方法が最適か。',
   NULL,
   '["インスタンスにネットワークタグを付け、そのタグを条件にした VPC ファイアウォールルールで許可範囲を定義する","VM 作成時にそれぞれ異なるゾーンを割り当てて、ゾーン単位で通信範囲を限定する","Cloud Load Balancing のバックエンド設定で通信元を絞り、ファイアウォール制御を省略する","Identity-Aware Proxy を使って、アプリケーションアクセスを認証制御する"]',
   0, NULL, 'single',
   '{"asked":"オートスケーリングで増減する VM 間の通信を、IP やゾーンに依存せずポート・方向単位で制御するには何を使うか。",
     "think":"オートスケーリングでは VM が動的に増減し、IP アドレスやゾーンで縛る制御はスケールのたびに再設定が必要になり破綻する。ネットワークタグは VM の実体（IP・ゾーン）とは独立した「ラベル」なので、新規インスタンスに同じタグを付けるだけで、既存のファイアウォールルールがそのまま適用される。ルールには通信方向（Ingress/Egress）と許可ポートを明示できるため、要件をそのまま満たせる。",
     "vs":"Identity-Aware Proxy はアプリケーション層でのユーザー認証・アクセス制御が主眼であり、ポート単位のネットワーク層制御には向かない。Cloud Load Balancing も HTTP(S) 分配が主用途で、内部通信のポート制御を代替するものではない。",
     "opt":["正解。ネットワークタグを条件にした VPC ファイアウォールルールなら、動的に増減するインスタンスにも一貫した通信方向・ポート制御を適用できる。","ゾーン単位の分離は管理単位として粗く、動的なスケーリングには追従しづらい。","Cloud Load Balancing は主に HTTP(S) トラフィックの分配用途であり、内部通信のポート制御には適していない。","Identity-Aware Proxy はアプリケーション層のアクセス制御が主眼であり、ネットワーク層のポート制御には向かない。"]}'),

  ('gcp-pca-g-q59', '信頼性の確保',
   'グローバルニュース配信アプリでは、トラフィック急増時に記事投稿処理の遅延が頻発している。アプリは Google Cloud Pub/Sub を利用しており、メッセージ送信エラーは検出されていないが、公開処理（publish）のレイテンシが高くなっている。リアルタイム性を優先して公開遅延を最小化したい場合、最も効果的な対応はどれか。',
   NULL,
   '["Pub/Sub のメッセージバッチングを無効化する","Pub/Sub のメッセージ保持期間を延長してメッセージの滞留を防ぐ","Pub/Sub トピックを複数作成し、アプリから送信先をラウンドロビンで分散する","サブスクリプションを Push から Pull に変更し、取得タイミングを制御する"]',
   0, NULL, 'single',
   '{"asked":"エラーは出ていないのに publish の応答が遅い、というケースで、最も直接的にレイテンシを下げる設定はどれか。",
     "think":"publish 側の遅延なので、原因を受信側（サブスクリプション形式）やトピック数、保持期間といった別レイヤーに求めても改善しない。Pub/Sub クライアントはデフォルトでメッセージをバッチにまとめてから送信するため、バッチが満たされるまでの待機がそのまま publish のレイテンシに乗る。バッチングを無効化すれば、この待機がなくなり単一メッセージあたりの応答が速くなる（スループットは犠牲になる）。",
     "vs":"保持期間・トピック分散・Push/Pull はいずれも「送信後にメッセージがどう扱われるか」に関わる設定で、publish の待機時間そのものには効かない。ボトルネックの層を正しく特定することが決め手になる。",
     "opt":["正解。バッチングを無効化すると、バッチが満たされるまでの待機がなくなり、単一メッセージあたりの publish レイテンシを大幅に下げられる。","保持期間の延長はメッセージ保存に関わる設定であり、送信速度やレイテンシ改善には無関係。","トピック分散は送信先を増やすだけで、単一メッセージの公開待機時間そのものは改善しない。","Push／Pull は受信方式の違いであり、publish 側の送信レイテンシには影響しない。"]}'),

  ('gcp-pca-g-q60', '設計・計画',
   '世界的な海洋輸送企業では、港湾での貨物積み下ろし作業の効率化を目的に、クレーン稼働ログ（毎時バッチ集計）と、積荷センサーから送られるリアルタイム位置イベントの両方を分析しようとしている。既存コードや分析基盤はなく、運用コストを最小限に抑えたい。この要件に最も適した選択肢はどれか。',
   NULL,
   '["Cloud Dataflow を用いて Apache Beam でバッチとストリーミングの統合パイプラインを構築する","Google Kubernetes Engine 上に Kafka Streams を自前構築し、Cloud SQL へ書き込む","Compute Engine 上でカスタムスクリプトを動作させ、Cloud Storage から BigQuery に定期ロードする","Cloud Dataproc を常時稼働クラスタとして構成し、Spark と Hadoop を併用する"]',
   0, NULL, 'single',
   '{"asked":"バッチ集計とリアルタイムイベントの両方を、既存基盤ゼロ・運用コスト最小で分析するには、どの基盤を選ぶべきか。",
     "think":"バッチとストリーミングを別々の仕組みで作ると、2 系統の運用コストがかかる。Apache Beam はこの 2 つを同一コードで統一的に扱えるモデルであり、Cloud Dataflow はそれをフルマネージドで動かせる。自動スケーリングと障害復旧も備えているため、インフラ運用の手間を増やさずに両方の要件を満たせる。Kafka Streams の自前構築や常時稼働の Dataproc クラスタは、いずれも「運用コストを最小限に」という前提と相性が悪い。",
     "vs":"Dataproc は既存の Hadoop/Spark 資産をそのまま移行するようなケースでは有力だが、今回のように新規構築で常時クラスタを維持すると、使っていない時間帯もコストが発生する。Dataflow はサーバーレスでその無駄がない。",
     "opt":["正解。Apache Beam ベースの Dataflow は同一コードでバッチとストリーミングを統合的に扱え、自動スケーリングも備えるためインフラ運用を最小化できる。","Kafka Streams を GKE 上に自前構築すると、クラスタや処理ロジックの運用を自分たちで担う必要があり負荷が高い。","カスタムスクリプトによる定期ロードではリアルタイム処理を扱えず、統合的な分析パイプラインを実現できない。","Dataproc を常時稼働クラスタとして構成すると、新規構築では稼働していない時間帯のコストがかさむ。"]}'),

  ('gcp-pca-g-q61', 'セキュリティとコンプライアンス',
   '国際的な医療機器リース会社では、クレジットカードによる定期課金システムを Google Cloud 上に構築している。医療関連データを扱うため、PCI DSS の準拠範囲を可能な限り縮小しつつ、売上傾向や利用頻度などの分析は継続したいと考えている。最も適切な設計方針はどれか。',
   NULL,
   '["トークナイゼーションを導入し、保存・分析はトークンのみを扱う","決済情報を暗号化して BigQuery に保存し、解析時に復号して利用する","決済データを扱うモジュールを独立した VPC に隔離して分析基盤と分離する","決済システム全体を PCI DSS 準拠リージョンに移設して対応範囲を限定する"]',
   0, NULL, 'single',
   '{"asked":"カード番号（PAN）を扱うシステムの PCI DSS 準拠範囲を縮小しつつ、分析目的の集計は続けたい場合、どう設計するか。",
     "think":"PCI DSS では PAN を保持するシステム全体が監査対象（CDE）になる。暗号化してもいずれ復号して使うなら PAN は依然として保持されており、スコープは縮小しない。リージョン移設や VPC 分離も、PAN そのものを扱う構成が残る限り根本的な解決にはならない。トークナイゼーションを導入し、決済処理以外のあらゆる箇所（分析基盤含む）ではトークンだけを扱うようにすれば、PAN を保持する範囲を決済処理部分だけに閉じ込められ、監査対象を最小化できる。",
     "vs":"「暗号化して復号して使う」と「トークン化してトークンのまま使う」は似て見えて範囲縮小の効果が全く違う。前者は PAN が形を変えて存在し続けるだけ、後者は PAN そのものを決済処理の外に出さない。",
     "opt":["正解。トークナイゼーションでカード番号をトークン化し、分析基盤ではトークンのみを扱うことで、PCI DSS の監査対象を決済処理部分に限定できる。","復号処理を伴う暗号化では PAN が依然として保持され、PCI DSS のスコープに含まれたままになる。","VPC 分離は補助的なセキュリティ対策に過ぎず、PAN を扱う限りスコープそのものは縮小できない。","リージョンを変更しても準拠範囲を技術的に縮小することにはならず、根本的な対策にはならない。"]}'),

  ('gcp-pca-g-q62', 'セキュリティとコンプライアンス',
   '国際イベントチケット販売プラットフォームでは、世界中の購入者によるクレジットカード決済を処理している。クレジットカード番号を平文で保持せずトークン化して保存しつつ、同一カードの重複判定を行いたいという要件がある。さらに、低レイテンシ・低コスト運用と暗号鍵の年次ローテーションが求められている。これらを最も効率的に満たす方法はどれか。',
   NULL,
   '["決定論的アルゴリズムで暗号化し、Firestore（Datastore モード）に保存する","Memorystore に保存し、キーごとに暗号化キーを動的生成する","Bigtable に保存し、暗号化後のデータを複数カラムに分割して管理する","Cloud Storage に保存し、保存前にカード番号ハッシュを別テーブルで照合する"]',
   0, NULL, 'single',
   '{"asked":"平文を保持せず、同一カードの重複判定もでき、低レイテンシ・低コストかつ鍵の年次ローテーションにも対応する保存方式はどれか。",
     "think":"「重複判定をしたい」が決め手になる。通常の（非決定論的な）暗号化は同じ入力でも毎回違う暗号文になるため重複判定ができない。決定論的暗号化なら同一の入力（カード番号）は常に同じ暗号化結果になるので、平文を保持せずに重複判定が可能になる。保存先には低レイテンシ・高スループットなトランザクション処理に向く Firestore（Datastore モード）を使い、Cloud KMS と連携すれば鍵の年次ローテーションも自動化できる。",
     "vs":"Memorystore はキャッシュ用途で永続保存や鍵管理を想定しておらず、Bigtable は分析向けで決済のリアルタイム照合には過剰設計、Cloud Storage は構造化照合に不向き。いずれも「重複判定」という要件を素直には満たせない。",
     "opt":["正解。決定論的暗号化なら同一カード番号が常に同じ暗号文になり平文なしで重複判定ができ、Firestore は低レイテンシで KMS 連携により鍵の年次ローテーションも自動化できる。","Memorystore はキャッシュ用途であり、永続保存や鍵管理を想定した設計ではない。","Bigtable は分析向けの設計であり、決済処理やリアルタイム照合の用途には過剰設計になる。","Cloud Storage は検索や重複検出に不向きで、構造化した照合処理を直接行えない。"]}'),

  ('gcp-pca-g-q63', '設計・計画',
   '世界海洋観測ネットワークでは、全海域からリアルタイムに収集される潮流・水温・塩分濃度などの観測ログをクラウド上で公開している。データ量は数ペタバイト規模に達し、研究者は標準 SQL で自由に集計・分析を行いたい。最も適したデータ保存および分析基盤はどれか。',
   NULL,
   '["BigQuery にロードしてデータウェアハウスとして管理する","Cloud Filestore にログをテキストとして保存し、都度スクリプトで解析する","Cloud Spanner にロードし、各センサー単位でトランザクション参照を行う","Firestore（ネイティブモード）へ観測ごとにドキュメント登録して検索する"]',
   0, NULL, 'single',
   '{"asked":"ペタバイト規模の観測ログを標準 SQL で自由に集計・分析したいとき、どの基盤に載せるべきか。",
     "think":"要件は「標準 SQL で」「ペタバイト規模を」「自由に集計」の 3 点。Cloud Filestore はファイル共有向けで SQL による集計を直接行えず、Cloud Spanner は OLTP のトランザクション処理向けで大規模な分析的集計には不向き、Firestore はドキュメント単位のクエリに最適化されておりスキャン型の大規模分析には非効率。BigQuery はサーバーレスのデータウェアハウスとして、標準 SQL のままペタバイト級データを高スループットに処理できるため、この 3 条件をそのまま満たす。",
     "vs":"「トランザクション処理に強い」（Spanner）と「大規模な分析集計に強い」（BigQuery）は別の得意分野。今回はリアルタイムの整合性より、後からの自由な SQL 集計が主目的なので BigQuery が適する。",
     "opt":["正解。BigQuery はサーバーレスのデータウェアハウスとして、標準 SQL のままペタバイト級データを高スループットに分析でき、スケーラビリティ・可用性の面でも最適である。","Cloud Filestore はファイル共有向けのサービスであり、SQL による集計処理を直接行うことはできない。","Cloud Spanner は OLTP のトランザクション処理向けであり、分析的な大規模集計には不向き。","Firestore（ネイティブモード）はドキュメント単位のクエリに最適化されており、スキャン型の大規模分析には非効率。"]}'),

  ('gcp-pca-g-q64', '実装の管理',
   'あるオンラインゲームプラットフォームでは、複数のゲームからスコアデータを受け取るための共通 API を提供している。ゲーム開発者との契約上、過去バージョンとの互換性を壊す変更がある場合でも、既存のタイトルに影響を与えないようにすることが求められている。安定運用を維持しつつ、非互換の仕様変更を安全に展開するには、どの対応が推奨されるか。',
   NULL,
   '["後方互換が壊れるたびに API のバージョン番号を上げる","クライアントアプリのアップデート後のみ API を更新することで整合性を保つ","新仕様で上書きして、既存 API のレスポンス形式を動的に変える","API エンドポイントはそのままにして、ヘッダーでバージョンを判別する"]',
   0, NULL, 'single',
   '{"asked":"共通 API に後方互換を壊す変更を入れつつ、既存タイトルへの影響をゼロにするには、どう API を進化させるべきか。",
     "think":"既存タイトルへの影響をゼロにするには、旧バージョンの動作をそのまま残しつつ新仕様を別物として提供する必要がある。後方互換が壊れるたびに API のバージョン番号を明示的に上げれば、旧バージョンのエンドポイントはそのまま動き続け、新しいタイトルだけが新バージョンに移行できる。開発者は自分のタイミングで移行時期を選べるため、安定運用と非互換変更の両立ができる。",
     "vs":"レスポンス形式をその場で上書きする方式や、クライアント側の更新に整合性を委ねる方式は、いずれも API 提供側で新旧の切り替えを制御できず、既存タイトルが意図せず新仕様の影響を受けてしまう。",
     "opt":["正解。後方互換が壊れるたびにバージョン番号を上げれば、旧バージョンを維持したまま新機能を段階的に導入でき、開発者が移行時期を柔軟に選べる。","クライアント側の更新に依存する方式では API 側から整合性を制御できず、既存タイトルへの影響を防げない。","レスポンス形式を動的に上書きする方式は動作の予測性を損ない、既存ユーザーへの影響が大きい。","ヘッダーでのバージョン判別はエンドポイントが1つに集約されて明示性に欠け、保守やテストが煩雑になる。"]}'),

  ('gcp-pca-g-q65', '信頼性の確保',
   '自動車製造業における部品在庫管理システムでは、定期的に在庫集計と補充ロジックを実行する必要がある。このジョブは Google Cloud 上で稼働する Compute Engine のユーティリティによって実行される。システム要件として、スケジューリングの可用性と再試行の保証が求められており、ジョブの取りこぼしが許されない。どの構成が最適か。',
   NULL,
   '["Cloud Scheduler から Cloud Pub/Sub のトピックへ発行し、Compute Engine 上のユーティリティがサブスクライブして処理する","Cloud Functions を利用してスケジューリングと処理の両方を一括で行う構成とする","GKE の CronJob を用いて、ジョブのスケジュールと実行を統合管理する","Cloud Scheduler から Compute Engine のエンドポイントへ直接 HTTP リクエストを送信する"]',
   0, NULL, 'single',
   '{"asked":"Compute Engine 上の既存ユーティリティを前提に、スケジューリングの可用性とジョブの取りこぼし防止を両立するには、どう構成するか。",
     "think":"「取りこぼしが許されない」という要件は、送信先が一時的にダウンしていても後で確実に処理されることを意味する。Cloud Scheduler から直接 HTTP でエンドポイントを叩く方式は、宛先がダウンしていればリクエストがそのまま失われる。Cloud Scheduler から Pub/Sub のトピックへメッセージを発行し、Compute Engine 側のユーティリティがサブスクライブして処理する構成にすれば、Pub/Sub が少なくとも 1 回の配送を保証するため、一時的な停止があっても復旧後にメッセージを処理でき、取りこぼしを防げる。",
     "vs":"Cloud Functions や GKE CronJob はそれぞれ便利な機能だが、前提の「Compute Engine 上の既存ユーティリティ」という構成とは別基盤になり、かつ Pub/Sub のような到達保証も持たない点で今回の要件に合わない。",
     "opt":["正解。Cloud Scheduler から Pub/Sub トピックへ発行し、Compute Engine 側がサブスクライブする構成なら、Pub/Sub の配送保証により一時停止があっても取りこぼさず処理できる。","Cloud Functions はイベント駆動・短時間処理向きで、既存の Compute Engine ユーティリティを前提とした構成とは異なり、スケジューリング機能も別途必要になる。","GKE の CronJob は別基盤となり前提構成と合致せず、Pub/Sub のような到達保証も持たない。","Cloud Scheduler からの直接 HTTP 通知では、宛先が一時的にダウンしているとリクエストが失われ、取りこぼしのリスクを排除できない。"]}'),

  ('gcp-pca-g-q66', 'インフラのプロビジョニングと管理',
   '次世代ロボット制御ソフトを開発する工業研究団体では、Linux 環境で動作する C++ による検証用テストスイートを日次で数百回実行している。オンプレミスの開発サーバーではリソースが不足し、夜間バッチに時間がかかりすぎていたため、最小限の変更でクラウド上へ移行し、テスト時間を大幅に短縮したいと考えている。この要件に最も適したクラウド基盤はどれか。',
   NULL,
   '["Compute Engine の管理型インスタンスグループ（MIG）にオートスケーリングを設定する","Cloud Build のビルドステップとして C++ バイナリを毎回実行する構成にする","Cloud Functions と Pub/Sub トリガーでテストスイートを非同期実行する","Cloud Run の自動スケーリング機能を用いてテストを並列実行する"]',
   0, NULL, 'single',
   '{"asked":"既存の C++ ネイティブバイナリをそのまま使い、最小限の変更でクラウド移行してテスト時間を短縮するには、どの基盤が適するか。",
     "think":"「最小限の変更で」「既存の C++ バイナリをそのまま」という条件がポイント。Cloud Functions や Cloud Run はコンテナ化やランタイム制約が前提になり、既存バイナリをそのまま持ち込むには改修が必要になる。Cloud Build はビルド用サービスであり、リソース集約型の長時間テストの実行には向かない。Compute Engine の MIG なら VM 上で C++ バイナリを直接そのまま実行しつつ、負荷に応じてインスタンス数を自動でスケールでき、並列度を上げてテスト時間を短縮しながら、不要時にはインスタンスを削除してコストも抑えられる。",
     "vs":"コンテナ化や関数化を要求する基盤（Cloud Run／Cloud Functions）は改修コストが発生する。VM ベースの MIG は「今あるバイナリをそのまま動かす」という制約に最も素直に応える。",
     "opt":["正解。MIG にオートスケーリングを設定すれば、既存の C++ バイナリをそのまま VM 上で並列実行でき、負荷に応じた自動スケールでテスト時間とコストの両方を最適化できる。","Cloud Build はビルド処理用のサービスであり、リソース集約型の長時間テストの実行には適さない。","Cloud Functions は C++ バイナリの実行に対応しておらず、ランタイム制約も厳しい。","Cloud Run はコンテナ化が前提であり、長時間実行や低レベルな環境制御には不向き。"]}'),

  ('gcp-pca-g-q67', '設計・計画',
   'ある音楽イベント運営会社では、期間限定でチケット販売を行うウェブサイトを Google Cloud 上に構築する計画がある。通常のアクセスは少ないが、販売開始直後には世界中から一斉にアクセスが集中するため、突発的なスパイクに耐えられる構成と、平常時のコスト効率が求められる。また、グローバルに高速な静的コンテンツ配信とトランザクション管理も必要である。Cloud Load Balancing を活用した場合、最も適切な構成はどれか。',
   NULL,
   '["Cloud CDN に静的コンテンツを配置し、API は Cloud Run にデプロイし、データは Cloud SQL に保存する","GKE オートパイロットクラスタにバックエンドを構築し、Cloud Storage で画像などを提供、Cloud Bigtable に保存する","Cloud Functions を API として使用し、静的コンテンツは Cloud Storage、データは Datastore に保存する","App Engine のスタンダード環境でアプリ全体を構築し、Cloud Memorystore をキャッシュ用途に使う"]',
   0, NULL, 'single',
   '{"asked":"突発的なアクセススパイクに耐えつつ平常時のコストも抑え、グローバル配信とトランザクション管理も両立する構成はどれか。",
     "think":"「静的コンテンツはグローバルに高速配信」「販売開始直後だけ跳ねるトラフィックにはゼロスケール前提でコストを抑える」「決済のようなトランザクションは信頼性の高い RDB で扱う」の 3 点を同時に満たす組み合わせを選ぶ。Cloud CDN は静的コンテンツのグローバル高速配信に、Cloud Run はスケールゼロ対応の自動スケーリングで平常時コストを抑えつつスパイクにも追従、Cloud SQL は信頼性の高いトランザクション処理を担う。3 者とも Cloud Load Balancing と自然に統合できる。",
     "vs":"GKE オートパイロットは強力だが小規模な期間限定サイトには過剰で、Bigtable はこの規模のトランザクション用途にはコスト・設計面で合わない。App Engine スタンダードは簡便な反面、自由度が低くコンテナ制御の柔軟性に欠ける。",
     "opt":["正解。Cloud CDN でグローバル高速配信、Cloud Run でゼロスケールとスパイク対応、Cloud SQL で信頼性の高いトランザクション処理を実現でき、Cloud Load Balancing とも統合しやすい。","GKE は強力だが小規模な期間限定サイトには過剰で、Bigtable はこのユースケースにはコスト・設計両面で適さない。","Cloud Functions はスパイク耐性があるが、大規模な REST API 構成には管理コストが増加する。","App Engine スタンダード環境は簡便だが自由度が低く、コンテナ制御や柔軟なリソース調整が難しい。"]}'),

  ('gcp-pca-g-q68', '設計・計画',
   '世界各国で利用されている気象予測 API を GKE クラスタ上で提供している気候シミュレーション研究所では、現在アジア地域（asia-southeast1）の拠点のみで運用している。最近、ヨーロッパの研究機関からの利用が増え、レスポンスタイムとシステム可用性の改善が強く求められている。ヨーロッパからのアクセスを最適化するために最も適切な対応はどれか。',
   NULL,
   '["europe-west1 に GKE クラスタを追加し、グローバル HTTP(S) ロードバランサで分散する","europe-west1 に VM インスタンスを個別に立て、DNS ラウンドロビンでルーティングする","europe-west1 の Cloud Functions を用いて API エンドポイントを複製する","asia-southeast1 の既存クラスタに Auto Scaling 設定を強化し、リクエスト処理能力を向上させる"]',
   0, NULL, 'single',
   '{"asked":"アジアのみで運用中の GKE 提供 API を、ヨーロッパからのレイテンシと可用性の両面で改善するには、どう構成を広げるか。",
     "think":"レイテンシの原因は物理的な距離そのものなので、単一リージョン内でどれだけスケーリングを強化しても解消しない（既存クラスタの Auto Scaling 強化では距離の問題は残る）。ヨーロッパ側にも GKE クラスタを追加し、グローバル HTTP(S) ロードバランサでユーザーの地理的近接性に応じてルーティングすれば、ヨーロッパのユーザーは近いリージョンで処理され、レイテンシが下がると同時に、リージョンが増えることでシステム全体の可用性も上がる。",
     "vs":"DNS ラウンドロビンや Cloud Functions での複製は、いずれも可用性やレイテンシを継続的なワークロードとして安定制御する仕組みを欠く。グローバルロードバランサによる地理ベースルーティングが、複数リージョン展開の正攻法になる。",
     "opt":["正解。europe-west1 に GKE クラスタを追加しグローバル HTTP(S) ロードバランサで分散すれば、地理的近接性に応じたルーティングでヨーロッパ向けレイテンシが下がり、全体の可用性も高まる。","DNS ラウンドロビンは可用性やレイテンシの制御に対応しておらず、管理も煩雑になる。","Cloud Functions はステートレスな短時間処理向きであり、継続的な API 提供には適さない。","単一リージョン内でのスケーリング強化では、地理的な距離による遅延そのものは解消できない。"]}'),

  ('gcp-pca-g-q69', '信頼性の確保',
   '大手出版社が運営する電子書籍配信プラットフォームでは、App Engine 上でアクセス負荷に応じたスケーリングを実施している。最近、キャンペーン期間中のアクセス集中時に、読了済みの書籍が再度「未読」として表示される事象が一部ユーザーで発生した。最も考えられる原因はどれか。',
   NULL,
   '["セッション変数が各インスタンスのローカルに保持されている","CDN キャッシュが誤ってユーザー状態を保持している","読了状態を URL パラメータで管理しており、URL の構成に揺らぎがある","クライアント側の Cookie がセッションごとに初期化されている"]',
   0, NULL, 'single',
   '{"asked":"アクセス集中時のスケーリングと連動して、既読情報が一部ユーザーだけ「未読」に戻る現象の原因は何か。",
     "think":"「アクセス集中時」「一部ユーザーだけ」という条件が、原因をインスタンス単位の状態管理に絞り込む手がかりになる。App Engine ではスケーリングによりインスタンスが増減し、リクエストのたびに異なるインスタンスへ振り分けられうる。もしセッション変数（既読情報）を各インスタンスのメモリにローカルに保持していると、別インスタンスに割り振られた瞬間にその情報が見えなくなり、「未読」に戻って見える。これはインスタンス間でメモリが共有されないという App Engine の性質そのものが原因になる。",
     "vs":"CDN キャッシュは静的コンテンツ向けでユーザーごとの状態管理とは無関係、URL パラメータの揺らぎやクライアント Cookie の初期化も、複数インスタンスへの分散スケーリングという条件とは結びつかない。「一部ユーザーだけ・負荷集中時だけ」起きる症状に最も整合するのはインスタンスローカルなセッション保持である。",
     "opt":["正解。インスタンスごとにメモリが分離されているため、セッションをローカルに保持していると、別インスタンスにルーティングされた際に既読情報が失われる。外部の共有ストアにセッションを持たせる必要がある。","CDN は静的コンテンツのキャッシュに適しているが、ユーザーごとのセッション管理とは関係がない。","URL 構成の揺らぎはキャッシュ制御に影響し得るが、セッション状態の分離とは関係がない。","クライアント側の Cookie 初期化は通常クライアント側で制御されるものであり、App Engine のスケーリングによるセッション不整合とは無関係。"]}'),

  ('gcp-pca-g-q70', 'セキュリティとコンプライアンス',
   '金融機関の社内基幹システムでは、オンプレミスで稼働中の Windows Server 2022 Datacenter を Google Cloud に移行する計画がある。同システムは既存の Microsoft ライセンスを保持しており、BYOL（Bring Your Own License）方式で利用を継続したいと考えている。ライセンス要件を満たしつつ、正しく移行・起動させるための最適な手順はどれか。',
   NULL,
   '["オンプレのイメージを作成し、--os=windows-2022 を指定してインポートしたうえで、Sole-Tenant Nodes 上のインスタンスでそのディスクをブートディスクとして起動する","Compute Engine の Windows Server 2022 Datacenter 共有イメージを使用して新規インスタンスを作成し、アプリのみを移行する","オンプレのイメージをそのまま Cloud Storage にアップロードし、Compute Engine で通常の共有ホストインスタンスとして起動する","オンプレ VM をエクスポート後、Cloud Run にコンテナ変換してデプロイする"]',
   0, NULL, 'single',
   '{"asked":"既存の Windows Server ライセンスを持ち込む（BYOL）形で Google Cloud に移行するには、どの手順が正しいか。",
     "think":"BYOL の要件は「Google 提供のライセンスを新たに購入するのではなく、自分たちが既に持つライセンスをそのまま使う」ことにある。Google 提供の共有イメージから新規作成すると、その時点で Google のライセンスが付与されてしまい BYOL にならない。正しくは、オンプレの Windows イメージそのものを --os=windows-2022 のような適切な OS フラグを指定してインポートし、ライセンス条件が定める Sole-Tenant Nodes（専有ノード）上でそのディスクをブートディスクとして起動する。これにより既存ライセンスを維持したまま Google Cloud 上で稼働できる。",
     "vs":"「共有イメージから新規作成」や「共有ホストインスタンスとして起動」は、どちらも結果的に Google 提供のライセンスを利用する形になり、持ち込みライセンス（BYOL）とはみなされない。専有ノードでのブートディスク起動という手順が BYOL の要件を満たす決め手になる。",
     "opt":["正解。オンプレイメージを --os=windows-2022 でインポートし、Sole-Tenant Nodes 上でそのディスクをブートディスクとして起動することで、既存ライセンスを活かした BYOL 構成を実現できる。","Google 提供の共有イメージから作成すると新たにライセンスが付与され、既存ライセンスの持ち込みではなく再購入する扱いになりBYOL要件を満たさない。","通常の共有ホストインスタンスとして起動すると Google 提供ライセンスを利用する形になり、BYOL とはみなされない。","Cloud Run はコンテナ実行環境であり、Windows Server ベースのフル VM ワークロードの移行先として不適切で、BYOL ライセンス要件も満たせない。"]}'),

  ('gcp-pca-g-q71', 'プロセスの分析と最適化',
   '大手オンライン図書館サービスでは、読者ごとに異なる推薦本リストをリアルタイムで表示している。推薦本のエンティティはすでに ID ベースでキャッシュに保持されているが、キャッシュミス時には Cloud Datastore（現 Firestore in Datastore モード）から高速かつ効率的にまとめてデータを取得する必要がある。API 呼び出し回数を最小限に抑えつつ、複数の本のエンティティを一括で取得するにはどうすればよいか。',
   NULL,
   '["各エンティティの Key を生成し、バッチ get で一括取得する","エンティティごとに JSON へ変換し、Pub/Sub 経由で非同期取得を行う","エンティティ ID の一覧をリクエストボディに渡し、全文検索 API を実行する","書籍 ID をフィルタ条件にしたクエリを 1 件ずつ送信し並列処理する"]',
   0, NULL, 'single',
   '{"asked":"ID（Key）が既にわかっている複数の書籍エンティティを、API 呼び出し回数を抑えつつ一括で取得するにはどうするか。",
     "think":"ID が既知であれば、クエリで探す必要はなく Key を直接指定して取得すればよい。各エンティティの Key を生成し、バッチ get を 1 回呼び出せば、複数エンティティをまとめて取得でき、API 呼び出し回数もレイテンシも最小化できる。Pub/Sub 経由の非同期化や全文検索、1 件ずつのクエリ送信は、いずれも「ID が既にわかっている」という前提を活かせておらず、遠回りになる。",
     "vs":"全文検索やフィルタクエリは「条件から探す」ための仕組みであり、正確な ID 指定によるバッチ get の代替にはならない。ID が既知のときは常に直接指定の一括取得が最短になる。",
     "opt":["正解。既知の Key を用いてバッチ get を1回呼び出せば、クエリを使わずID指定で直接取得でき、API 呼び出し回数とレイテンシの両方を最適化できる。","Pub/Sub 経由の非同期処理はオーバーヘッドが増え、リアルタイム取得には適していない。","全文検索は条件検索向けの仕組みであり、正確な ID 指定には向かない非効率な手法になる。","ID ごとの個別クエリを並列送信してもリクエスト回数とコストが増加し、最適な方法ではない。"]}'),

  ('gcp-pca-g-q72', 'インフラのプロビジョニングと管理',
   '映画制作スタジオでは、過去作品の映像素材（約 10TB）を他社クラウドストレージに保管している。新しい AI 編集システムを Google Cloud 上に構築するため、これらの映像データを Cloud Storage に移行する必要がある。移行コストを抑えつつ、できるだけ短時間で完了させたい場合、最も適切な方法はどれか。',
   NULL,
   '["Storage Transfer Service を利用する","Cloud Dataflow でストリーミング転送ジョブを作成する","データを圧縮してメール添付で送信する","手動で API 経由のコピー処理をスクリプト化する"]',
   0, NULL, 'single',
   '{"asked":"他社クラウドストレージにある約10TBの映像データを Cloud Storage に、低コストかつ短時間で移行するには何を使うか。",
     "think":"大容量データを他クラウドから Cloud Storage へ移す用途に特化したマネージドサービスがあるかどうかがポイント。Storage Transfer Service は AWS S3・Azure Blob・オンプレファイルサーバーなどから Cloud Storage への移行を自動化し、並列転送・再試行・差分同期を備えているため、手動運用より高速かつ安定して低コストに完了できる。Dataflow は ETL 向けで単純な転送には非効率、メール添付は現実的でなく、手動 API スクリプトは並列化や再試行を自前で実装する必要があり運用負荷が高い。",
     "vs":"「データ変換を伴う処理」（Dataflow）と「純粋なファイル移行」（Storage Transfer Service）は目的が異なる。今回は変換不要の単純移行なので、専用の移行サービスを使うのが最短・低コストになる。",
     "opt":["正解。Storage Transfer Service は他社クラウドからの移行を自動化するマネージドサービスで、並列転送・再試行・差分同期により手動運用より高速かつ低コストに移行できる。","Cloud Dataflow は ETL やデータ変換向けの分散処理サービスであり、単純なファイル転送には非効率。","メールでの送信はファイルサイズ制限やセキュリティの観点から現実的ではない。","API スクリプトでの手動コピーは並列化や再試行処理を自前で実装する必要があり、運用負荷が高くなる。"]}'),

  ('gcp-pca-g-q73', '設計・計画',
   'スマートシティの交通分析システムでは、同一リージョン内に 2 つのサブネットを構成している。sub-a は公開 IP 付きの管理用サブネット、sub-b は外部公開を禁止された解析用プライベートサブネットである。現在、sub-b 上の VM が外部のオープンソースリポジトリからパッケージを取得する必要がある。セキュリティを保ちつつ、この通信を実現する最適な方法はどれか。',
   NULL,
   '["Cloud NAT を構成し、NAT マッピングに sub-b を指定する","sub-a にプロキシサーバを構築して、sub-b から転送する","sub-b に Private Google Access を有効化して外部リポジトリへアクセスする","IAP の TCP トンネルを利用して外部通信を行う"]',
   0, NULL, 'single',
   '{"asked":"公開 IP を持たないプライベートサブネットの VM から、外部の一般公開リポジトリへ安全にアウトバウンド通信するにはどうするか。",
     "think":"要件は「公開 IP は持たせない」「外部（非 Google）の一般サイトへアクセスしたい」の 2 つ。Private Google Access は Google の API やサービス専用であり、一般の外部サイトには使えない。IAP の TCP トンネルは管理者が内部リソースへ入っていくための仕組みで、通常のアウトバウンド通信の代替にはならない。Cloud NAT はプライベート VM のアウトバウンド通信だけを、公開 IP を持たせずに外部へ到達させる機能で、まさにこの要件に合致する。",
     "vs":"プロキシサーバを別サブネットに立てる方式でも技術的には実現できるが、構成が複雑になり運用・スケーラビリティの負担が増える。Cloud NAT はマネージドな仕組みとして同じ目的をより単純に達成できる。",
     "opt":["正解。Cloud NAT はプライベート VM のアウトバウンドのみを許可し、公開 IP を持たせずに非 Google の外部リポジトリへ到達できる。","プロキシ経由の構成は複雑になり、スケーラビリティと運用負担の点で非効率。","Private Google Access は Google の API やサービス専用であり、一般の外部サイトへは接続できない。","IAP は内部リソースへの管理アクセス用であり、通常の外向き通信を行う用途には不適切。"]}'),

  ('gcp-pca-g-q74', '設計・計画',
   '宇宙観測データ処理センターでは、現在すべてのアプリケーションを Compute Engine 上の仮想マシンで運用している。今後 9 か月以内に保守作業を極力排除し、トラフィックに応じて自動でスケール可能なクラウドネイティブ基盤へ移行する計画である。NoOps（運用不要）志向とスケーラビリティを重視した場合、採用すべき基盤の組み合わせとして最も適切なのはどれか（2 つ選択）。',
   NULL,
   '["Cloud Run","App Engine Standard","Dataproc VM ベースクラスタ","Google Kubernetes Engine（GKE）","Cloud Functions"]',
   0, '[0,1]', 'multi',
   '{"asked":"保守作業を極力排除しつつ自動スケールも実現するクラウドネイティブ基盤として、最も NoOps 志向が強い 2 つはどれか。",
     "think":"「保守作業を極力排除」＝サーバー管理・パッチ適用・クラスタ管理を自分たちでやらなくてよいことが条件になる。GKE は強力だがクラスタ自体のバージョン管理などの運用作業が残り、Dataproc VM ベースクラスタは分析向けでそもそも NoOps 志向に合わない。Cloud Functions は単発イベント処理には向くが Web アプリや長時間処理のホストには制約がある。App Engine Standard はスケーリング・パッチ適用・サーバ管理を丸ごと不要化する完全マネージド PaaS、Cloud Run はコンテナベースで自動スケーリングとスケールゼロに対応し、デプロイ後は完全マネージド運用になる。この 2 つの組み合わせが、開発者をインフラ管理から最も解放する。",
     "vs":"GKE は「マネージド」ではあるが「NoOps」ではない――クラスタのアップグレードや構成管理という運用作業が残る点が、App Engine Standard や Cloud Run との決定的な違いになる。",
     "opt":["正解。Cloud Run はコンテナベースで自動スケーリングとスケールゼロに対応し、デプロイ後は完全マネージドで運用できる。","正解。App Engine Standard は完全マネージドな PaaS として、スケーリング・パッチ適用・サーバ管理を不要化しNoOpsを実現する。","Dataproc VM ベースクラスタは分析向けのクラスタ運用であり、NoOps志向には適さない。","GKE はマネージド Kubernetes ではあるが、クラスタ管理やバージョン管理などの運用作業が残る。","Cloud Functions はイベント駆動処理に最適だが、Web アプリや長時間処理をホストするには制約がある。"]}'),

  ('gcp-pca-g-q75', '設計・計画',
   '国際物流衛星トラッキングシステムでは、低軌道衛星から受信したテレメトリイベント（サイズ：50KB〜15MB）を Cloud Storage にリアルタイムで蓄積し、後に地上処理センターで解析を行っている。ピーク時は 1 秒あたり約 3,000 件のイベントが発生する。取りこぼしを最小限に抑えつつ、高スループットかつ分析しやすい形式で保存する最も効果的な手法はどれか。',
   NULL,
   '["イベント本体に必要メタデータを埋め込み、個別ファイルを圧縮。オブジェクト名はランダム接頭辞（シャーディング）を用い、単一バケットに継続投入する","ファイル保存後に Cloud Run で逐次処理し、ログ整理用バケットへ再配置する","衛星ごとに専用バケットを作成し、全イベントを日次でアーカイブ化して格納する","イベントごとに Cloud Function で Pub/Sub 通知をトリガーし、BigQuery にメタデータを直接書き込む構成とする"]',
   0, NULL, 'single',
   '{"asked":"秒間約3,000件・大容量のイベントを、取りこぼしなく高スループットかつ後で分析しやすい形で Cloud Storage に保存するには、どう設計するか。",
     "think":"高頻度な書き込みでは、Cloud Storage のオブジェクト名の付け方自体がスループットに影響する（連番のような先頭が揃った命名はホットスポットになりやすい）。ランダムな接頭辞でオブジェクト名を分散（シャーディング）させれば、書き込みが特定のパーティションに集中せず高スループットを保てる。イベント本体にメタデータを埋め込み個別ファイルとして圧縮すれば、転送効率とストレージコストも最適化でき、単一バケットに構造化された命名規則で継続投入することで、後段の解析や運用も簡素化できる。",
     "vs":"衛星ごとの専用バケットや日次アーカイブは管理単位が粗くなり再処理に不向き、逐次処理での再配置は遅延や並列性の制約を招く。BigQuery への直接書き込みはリアルタイム処理向けであり、大量オブジェクトそのものの保存には不向き。",
     "opt":["正解。メタデータを埋め込んだ個別ファイルを圧縮し、ランダム接頭辞でオブジェクト名を分散させることで、書き込みの集中を避けつつ転送効率とストレージコストを最適化し、単一バケットで解析・運用も簡素化できる。","Cloud Run による逐次転送は遅延や並列性の制約を招き、高負荷下では処理しきれない可能性がある。","衛星ごとの専用バケットや日次アーカイブはスケーラビリティと管理性に欠け、アーカイブ単位も大きすぎて再処理に不向き。","BigQuery への直接書き込みはリアルタイム処理向けであり、大量オブジェクトの保存そのものには不向き。"]}'),

  ('gcp-pca-g-q76', 'プロセスの分析と最適化',
   '動画配信サービスで、特定の時間帯に視聴開始までの待機時間が長くなる現象が発生している。原因が分からず、配信経路のどこかに遅延があると疑われている。最も効果的にボトルネックの発生箇所を特定する手法はどれか。',
   NULL,
   '["Cloud Trace を導入し、リクエストフローを可視化する","VPC フローログを有効化して通信ログを収集する","CDN キャッシュの有効期限を延長する","Cloud Scheduler で定期的に配信サービスを再起動する"]',
   0, NULL, 'single',
   '{"asked":"配信経路のどこに遅延があるか分からない状態で、最も効果的にボトルネックの発生箇所を突き止める手法はどれか。",
     "think":"原因不明の遅延を特定するには、まずリクエストがどのサービスをどれだけの時間かけて通過しているかを可視化する必要がある。Cloud Trace はリクエストの経路と各区間のレイテンシを可視化でき、どのサービスがボトルネックになっているかを直接特定できる。VPC フローログはネットワークレベルの情報しか得られずアプリケーション内部の遅延は分からず、キャッシュ延長や再起動は根本原因を調べずに症状を一時的に和らげようとするだけで、原因特定にはつながらない。",
     "vs":"「原因を推測して対策を打つ」（再起動、キャッシュ延長）のではなく、「まず可視化して原因を特定する」（Cloud Trace）ことが、原因不明の遅延に対する正しい最初の一手になる。",
     "opt":["正解。Cloud Trace はリクエストの経路を可視化でき、どのサービスが遅延の原因となっているかを特定できる。","VPC フローログではネットワークレベルの情報しか得られず、アプリケーション内部の遅延までは把握できない。","CDN キャッシュの有効期限を延ばしても、遅延の根本的原因を解決できるとは限らない。","定期的な再起動は一時的な緩和にしかならず、原因特定や恒久的な対策にはつながらない。"]}'),

  ('gcp-pca-g-q77', 'プロセスの分析と最適化',
   '国際的な教育支援団体では、複数国のプロジェクトマネージャーが BigQuery、Bigtable、GKE を利用して学習データ分析基盤を運用している。各メンバーは出張先や自宅など、異なる端末やネットワークから gcloud CLI を操作する必要がある。環境を統一し、常に最新ツールを利用できるようにする最も効率的な方法はどれか。',
   NULL,
   '["Google Cloud Shell を利用する","Organization Policy で CLI 設定ファイルを強制的に同期する","各メンバーの端末に Docker コンテナで共通 CLI 環境を配布する","Cloud Workstations を構築して全メンバーで共有する"]',
   0, NULL, 'single',
   '{"asked":"異なる端末・ネットワークから作業する複数メンバーの gcloud CLI 環境を、常に最新かつ統一された状態に保つには何が最も効率的か。",
     "think":"端末ごとに環境を配布・同期する方式（Docker 配布、Organization Policy での設定同期）は、更新のたびに配布や同期の作業が発生し、完全な統一には手間が残る。Google Cloud Shell はブラウザから使える統一環境そのものであり、常に最新の gcloud CLI があらかじめ用意されているため、端末やネットワークに依存せず誰がどこからアクセスしても同じ環境になる。追加の構築や配布作業も不要。",
     "vs":"Cloud Workstations は開発用途の共有環境として便利だが、構築・運用コストが高く今回の「CLI 操作の環境統一」という比較的軽い要件には過剰。Cloud Shell はより軽量にその目的を満たす。",
     "opt":["正解。Google Cloud Shell はブラウザベースの統一環境として常に最新の gcloud CLI を提供し、複数の端末・ネットワークをまたぐ利用にも追加構築なしで対応できる。","Organization Policy では CLI 設定内容そのものの同期は制御できず、環境統一の目的を果たせない。","Docker コンテナでの環境配布は各端末での構築・更新作業が発生し、環境統一の手間を完全には解消できない。","Cloud Workstations は開発用途向けの環境で、運用コストが高く管理も複雑になる。"]}'),

  ('gcp-pca-g-q78', '信頼性の確保',
   'とある遺伝子解析ラボでは、超高精度なゲノム解析アプリを Google Cloud の Compute Engine 上でアクティブ-パッシブ構成により運用している。実行ノードは同一リージョン内の異なるゾーンに配置され、解析中に記録される一時データの可用性が極めて重要である。障害発生時でも即座にフェイルオーバーでき、かつストレージ性能を最大限に活用する構成として最も適切なのはどれか。',
   NULL,
   '["1 台目にリージョナル SSD 永続ディスクを接続し、障害時にもう一方へ強制アタッチする","分散ファイルシステムを使い両ノード間でリアルタイム同期を行い、ファイル整合性を確保する","1 台目にローカル SSD を構成し、仮想ディスクで RAID1 を組んでミラーリングを実施する","1 台目に Balanced 永続ディスクを接続し、定期的に Cloud Functions でスナップショットを自動取得する"]',
   0, NULL, 'single',
   '{"asked":"同一リージョン内の異なるゾーンにまたがるアクティブ-パッシブ構成で、即座のフェイルオーバーと高いディスク性能を両立するには、どのディスク構成が適するか。",
     "think":"「即座に」フェイルオーバーしたいなら、障害発生の時点でデータがすでに別ゾーンにも存在している必要がある。ローカル SSD は揮発性でありノード障害時にデータ自体を失うため要件を満たさず、スナップショットによる定期取得は取得間隔の分だけデータ損失のリスクが残る。リージョナル SSD 永続ディスクは同一リージョン内の 2 つのゾーンにまたがってブロックレベルで同期されているため、障害発生時にもう一方のゾーンへ即座に強制アタッチして解析を継続でき、SSD による高いディスク性能も確保できる。",
     "vs":"分散ファイルシステムによるリアルタイム同期でも同様のことは狙えるが、整合性維持のための構成が複雑になりレイテンシも高くなる。リージョナル SSD はこれをマネージドな形でより単純に実現する。",
     "opt":["正解。リージョナル SSD 永続ディスクは2つのゾーンにわたりブロックレベルで同期されているため、ゾーン障害時でも即座に別ノードへ再アタッチでき、SSDによる高い性能も確保できる。","分散ファイルシステムによる整合性維持には複雑な構成が必要でレイテンシも高くなる。","ローカル SSD は揮発性があるため、障害発生時にデータを保持できず可用性の要件を満たせない。","スナップショット方式では取得間隔の分だけデータ損失のリスクが残る。"]}'),

  ('gcp-pca-g-q79', '設計・計画',
   '大規模音楽イベントのプロモーションを担当するマーケティング部門では、特設キャンペーンサイトへのリンクを含んだメールを一斉配信し、クリックユーザーの選好情報（例：ジャンル、アーティスト）を収集したいと考えている。アクセス数は数百件から数十万件/日に変動し、開発チームは手動対応を極力避けて、完全マネージドな構成で運用したいとしている。この目的を最も効率的に実現できる構成はどれか。',
   NULL,
   '["App Engine Standard でサイトを配信し、ユーザーデータを Firestore に保存する","Managed Instance Group を構成し、バックエンドで Cloud Bigtable にデータを書き込む","Cloud Functions で HTML を配信し、ログを Pub/Sub 経由で Cloud Storage に保存する","Compute Engine の単一 VM に Apache を構築し、Cloud SQL にデータを格納する"]',
   0, NULL, 'single',
   '{"asked":"数百〜数十万件/日という大きく変動するアクセスに、手動対応ゼロの完全マネージド構成で対応するには、どの組み合わせが適するか。",
     "think":"アクセス数の変動幅が極端に大きいため、インフラの手当てをその都度人が行う構成（単一 VM、Managed Instance Group）は「手動対応を極力避けたい」という要件と相性が悪い。App Engine Standard は Web アプリをフルマネージドで提供し、アクセス急増時も自動スケーリングで追従する。Firestore はサーバーレスでスキーマレスなドキュメント DB として、ユーザーごとの選好データを容易に保存・照会できる。この組み合わせなら NoOps のままスケーラブルな運用が実現する。",
     "vs":"Cloud Functions によるイベント駆動処理は単発の軽い処理には向くが、HTML 配信やセッションを伴うサイト全体のホスティングには不向き。Web アプリのホスティングという用途には App Engine Standard の方が適する。",
     "opt":["正解。App Engine Standard はアクセス急増時も自動スケーリングで対応するフルマネージド環境で、Firestore はサーバーレスでユーザー選好データを容易に保存・照会でき、NoOpsかつスケーラブルな構成を実現できる。","Managed Instance Group は柔軟だがインフラ管理が必要であり、NoOps の要件に合致しない。","Cloud Functions はイベント駆動処理に適しているが、HTML 配信やセッションを伴うサイト運用には不向き。","単一 VM 構成はスケーラビリティがなく、手動運用の負荷が高い。"]}'),

  ('gcp-pca-g-q80', 'セキュリティとコンプライアンス',
   'スマートシティ向け交通分析システムでは、BigQuery に市民の移動履歴データを蓄積している。このデータには一部 PII（個人情報）が含まれている。運用チームは、監査部門のみが PII にアクセスでき、データサイエンスチームには匿名化済みデータのみを提供したいと考えている。コストを抑えつつ安全に運用するための最適な設計はどれか。',
   NULL,
   '["データサイエンス専用のデータセットを作成し、PII を除外したビューを配置してアクセス権を分離する","BigQuery のデータマスキング機能を全カラムに適用して分析に使用する","同一データセット内に匿名化テーブルを作成し、アクセス権をテーブル単位で制御する","PII を除外した CSV ファイルをエクスポートし、データサイエンスチームに配布する"]',
   0, NULL, 'single',
   '{"asked":"同じ BigQuery 上のデータで、監査部門には生データを、データサイエンスチームには匿名化データだけを、低コストかつ安全に提供するにはどう設計するか。",
     "think":"データを物理的に複製・配布する方式（CSV エクスポート）は更新のたびに再配布が必要でセキュリティ・運用コストの両面で重い。同一データセット内でテーブル単位のアクセス権を分ける方式は、設定ミスひとつで生データに触れてしまうリスクが残る。データサイエンス専用のデータセットを別に作り、そこに PII を除外したビューだけを置いてアクセス権を分離すれば、「監査部門：生データ」「データサイエンス：匿名化ビュー」という境界がデータセット単位で明確になる。ビューを承認付きビュー（Authorized View）にしてソースデータセットへのアクセスを付与すれば、元データを複製せずにセキュリティとコスト効率を両立できる。",
     "vs":"データマスキングは主にリアルタイムのクエリ結果を動的に加工する仕組みで、統計分析用途において「完全な匿名化」を保証するものではない点に注意。今回のような恒久的なアクセス分離には、データセットとビューによる分離の方が確実。",
     "opt":["正解。PII を除外したビューをデータサイエンス専用のデータセットに配置し承認付きビューとしてアクセスを付与すれば、生データと匿名化データを厳格に分離しつつコスト効率も両立できる。","データマスキングはリアルタイム処理向けであり、統計分析用途で完全な匿名化を保証するものではない。","同一データセット内での匿名化テーブル運用はアクセス誤設定のリスクが残り、分離の効果が限定的になる。","CSV ファイルの配布は更新管理・セキュリティ管理のコストが高く、運用上非効率になる。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'gcp-pca-g'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
